import { Context, Effect } from 'effect'
import type { OrbitArtifactRef } from './orbit'
import type { PluginTool, ToolInvocationResult } from './plugin'
import type { PluginRegistryEntry } from './registry'
import type { CreateRunBody, Run } from './run'
import type { RuntimeExecutionRequest, RuntimeExecutionResult } from './runtime'
import type { RunId, SecretName, SourceNamespace, ToolId, WorkspaceId } from './scalars'
import type { Source } from './source'

export interface WorkspaceAuthorizer {
  readonly requireWorkspaceAccess: (
    workspaceId: WorkspaceId,
    action: string
  ) => Effect.Effect<void, WorkspaceAuthorizationError>
}

export class WorkspaceAuthorizationError extends Error {
  readonly _tag = 'WorkspaceAuthorizationError'
  constructor(
    readonly workspaceId: WorkspaceId,
    readonly action: string,
    readonly reason: string
  ) {
    super(reason)
    this.name = 'WorkspaceAuthorizationError'
  }
}

export const WorkspaceAuthorizer = Context.Service<WorkspaceAuthorizer>(
  '@hrbr/core/WorkspaceAuthorizer'
)

export interface RunStore {
  readonly create: (body: CreateRunBody) => Effect.Effect<Run, RunStoreError>
  readonly get: (workspaceId: WorkspaceId, runId: RunId) => Effect.Effect<Run, RunStoreError>
  readonly complete: (
    workspaceId: WorkspaceId,
    runId: RunId,
    output: unknown
  ) => Effect.Effect<Run, RunStoreError>
  readonly fail: (
    workspaceId: WorkspaceId,
    runId: RunId,
    error: string
  ) => Effect.Effect<Run, RunStoreError>
}

export class RunStoreError extends Error {
  readonly _tag = 'RunStoreError'
  constructor(readonly reason: string) {
    super(reason)
    this.name = 'RunStoreError'
  }
}

export const RunStore = Context.Service<RunStore>('@hrbr/core/RunStore')

